/* Host model (see msnrept.c). Group/side selection, record lookups, byte and
 * string arithmetic run recovered host code; scripted services are
 *   0 rand_bounded(bound)  1 request_text(id)  3 control_message(text,person)
 *   4 daily_show(id,side,offset,segment)  9 set_turn_context(v)
 *   10 finish_side_initialization(v), plus those of the report helpers. */
#define PTR        uint16_t
#define TEXT_P     uint16_t
#define MISSION_P  uint16_t
#define MISSION(s) ((uint16_t)(0x21a + (s) * 65 + 61))
#define WORD(a)   ((uint16_t)(ds[(uint16_t)(a)] | ds[(uint16_t)((a) + 1)] << 8))
#define TARGET(m) WORD(m)
#define FIELD(p, n)  ds[(uint16_t)((p) + (n))]
#define NEXT(p)      WORD(p)
#define STATUS(s)    WORD(0x5a + (s) * 2)
#define BOLD_OFF     0x7a27
#define RATING(s, k) opeu_officer_rating(ds, s, k)
#define GAIN(s, k)   opeu_officer_gain(ds, s, k)
#define SUCCESS(s, t, x, y) \
  opeu_mission_report_success(ds, event, frame, s, t, x, y)
#define FAILURE(s, t)        opeu_mission_report_failure(ds, event, frame, s, t)
#define TARGET_NAME(s, u, d) opeu_mission_target_name(ds, event, frame, s, u, d)
#define KILLED(p)            opeu_mission_person_killed(ds, event, frame, p)
#define FIND(s, k)           opeu_find_side_record(ds, s, k)
#define GROUP_RECORD(s, g)   opeu_find_group_record(ds, s, g)
#define OPPOSITE(s)          opeu_opposite_side(s)
#define PERSON_SIDE(p)       opeu_person_lacks_side0_flag(ds, p)
#define UNIT_GROUP(u)        opeu_unit_group(u)
#define GROUP_SELECTED(g)    opeu_find_group_selected_unit(ds, g)
#define GROUP_INDEX(u)       opeu_unit_group_index(u)
#define SIDE_SELECTED(s)     opeu_find_side_selected_unit(ds, s)
#define RAND(n)              event(ds, 0, (uint16_t[]){ n }, 1)
#define SUB(n, p)            opeu_sub_byte(n, p)
#define TEXT(n)              event(ds, 1, (uint16_t[]){ n }, 1)
#define COPY(d, s)           opeu_string_copy(ds, d, s)
#define APPEND(d, s)         opeu_string_append(ds, d, s)
#define MESSAGE(t, p)        event(ds, 3, (uint16_t[]){ t, p }, 2)
#define SHOW_DELAY(s) event(ds, 4, (uint16_t[]){ 0x12c, s, 0x004a, 0x0e8e }, 4)
#define CONTEXT(v)    event(ds, 9, (uint16_t[]){ v }, 1)
#define FINISH(v)     event(ds, 10, (uint16_t[]){ v }, 1)
#define BUF(n, size)  uint16_t n = (frame = (uint16_t)(frame - (size)))
/* C 6.0a evaluates this call's source argument first; keep that order. */
#define HOST_TEMPS uint16_t host_source;
