      frame = port_frame_enter();
      opeu_objective_damage(ds, svc_objdamag, frame, ARG(0), ARG(1), ARG(2),
                            ARG(3), ARG(4), ARG(5), ARG(6));
      port_frame_leave();
      break;
    case 8: /* 17c4:0b1c */
      frame = port_frame_enter();
      opeu_unit_casualties(ds, svc_casualty, frame, ARG(0), ARG(1), ARG(2),
                           ARG(3), ARG(4), ARG(5));
      port_frame_leave();
      break;
    case 9:
      opeu_set_turn_context(ds, svc_sound, (uint8_t)ARG(0));
      break; /* 0d65:00fe */
    case 10:
      opeu_finish_side_initialization(ds, svc_sound, (uint8_t)ARG(0));
      break;                                            /* 0d65:0032 */
    case 11: opeu_initialize_deputy(ds, ARG(0)); break; /* 0b73:048a */
    case 12:
      opeu_pending_finish(ds, svc_waitkey, (uint8_t)ARG(0));
      break; /* 0a8e:005c */
    case 13:
      opeu_delay_units(ds, svc_waitkey, (uint8_t)ARG(0));
